function ftShow(f){ const s=f.txt; if(typeof s!=='string'||f.label) return s; if(f._txE===s&&f._txL===LANG.cur) return f._tx;
  let o=s, m; const k=FT_I18N[s]; if(k) o=ewT(k)||s; else if((m=/^FED \+(\d+)%$/.exec(s))) o=ewT('fx2.fed_pct',{n:m[1]})||s;
  else if((m=/^bleed x(\d+)$/.exec(s))) o=ewT('fx2.bleed_x',{n:m[1]})||s; else if((m=/^wax x(\d+)$/.exec(s))) o=ewT('fx2.wax_x',{n:m[1]})||s;
